# owner: platform
import unittest

from hourglass.rounding import round_span, rounded_labels
from hourglass.models import Span

class RoundSpanTests(unittest.TestCase):
    def test_snaps_to_nearest(self):
        got = round_span(Span(542, 1027), 15)
        self.assertEqual(got, Span(540, 1020))

    def test_halves_round_up(self):
        got = round_span(Span(67, 128), 15)
        self.assertEqual(got, Span(60, 135))

    def test_exact_values_stay(self):
        got = round_span(Span(540, 600), 30)
        self.assertEqual(got, Span(540, 600))

    def test_collapsed_span_raises(self):
        with self.assertRaises(ValueError):
            round_span(Span(540, 545), 15)

class LabelTests(unittest.TestCase):
    def test_label_format(self):
        got = rounded_labels([Span(541, 1034)], 15)
        self.assertEqual(got, ["09:00-17:15 (8h 15m)"])

    def test_one_label_per_span(self):
        spans = [Span(60, 120), Span(480, 510)]
        got = rounded_labels(spans, 30)
        want = ["01:00-02:00 (1h 0m)"]
        want.append("08:00-08:30 (0h 30m)")
        self.assertEqual(got, want)

    def test_empty_list(self):
        self.assertEqual(rounded_labels([], 15), [])

class StepTests(unittest.TestCase):
    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 90):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    rounded_labels([Span(60, 120)], step)

    def test_bad_step_with_no_spans(self):
        with self.assertRaises(ValueError):
            rounded_labels([], 0)
